-- Learn Languages App - Migration
-- Migration: 20261106000001-frases-hechas-trocear-por-frecuencia
-- Description: Eduardo (2026-11-06): «vamos a trocear el grupo 55 en 2 grupos de 50 y el resto, prioricemos
--   por frecuencia de uso de las frases en el habla coloquial».
--
--   El grupo 55 se renombra a 'frases hechas 1 - las 50 más usadas' y se queda con las 50 expresiones más oídas hoy (PHRASE + su SENTENCE,
--   100 tarjetas). Las 41 restantes pasan, con su SENTENCE, al grupo nuevo 'frases hechas 2 - las 41 siguientes' (82 tarjetas). Siguen todas en
--   generic. El grupo 56 'para más adelante' no cambia. Orden por criterio propio de uso coloquial (no hay
--   corpus de expresiones): geen flauw idee hebben, voor de zekerheid, om de hoek, geen sprake van, aan de slag, zomaar ineens, de wereld is klein, beter laat dan nooit, iemand voor de gek houden, iemand op de zenuwen werken, …
--   Pasan al 2: een flater slaan, het regent pijpenstelen, spreken is zilver, zwijgen is goud, een gegeven paard niet in de bek kijken, wat niet weet, wat niet deert, beter één vogel in de hand dan tien in de lucht, te veel hooi op je vork nemen, het beestje bij zijn naam noemen, tussen hamer en aambeeld zitten, spijkers op laag water zoeken, twee handen op één buik zijn, als een boemerang terugkomen, er niets van bakken, een ongeluk komt zelden alleen, mosterd na de maaltijd, iemand een kat in de zak verkopen, de koe bij de hoorns vatten, ter zake komen, platzak zijn, geld over de balk gooien, zich in iemand verplaatsen, de kastanjes uit het vuur halen, de touwtjes in handen hebben, met de armen over elkaar zitten, de aanhouder wint, het is niet alles goud wat er blinkt, blaffende honden bijten niet, moord en brand schreeuwen, Oost-Indisch doof zijn, als je het over de duivel hebt, door een roze bril kijken, je nek uitsteken, korte metten maken met, de huid niet verkopen voordat de beer geschoten is, het water staat je tot aan de lippen, een kruiwagen hebben, je slag slaan, dat is andere koek, zich te goed doen aan, iemand op heterdaad betrappen, zo koppig als een ezel zijn.

PRAGMA foreign_keys = ON;

UPDATE word_groups
   SET title = 'frases hechas 1 - las 50 más usadas',
       description = 'Las 50 frases hechas más oídas hoy en el habla coloquial, con su equivalente idiomático neerlandés dentro de una frase de uso diario, palabra a palabra, contexto y registro. Las siguientes 41 están en el grupo frases hechas 2.',
       updated_at = datetime('now')
 WHERE title = 'frases hechas - uitdrukkingen en spreekwoorden';

INSERT INTO word_groups (title, description, source)
SELECT 'frases hechas 2 - las 41 siguientes',
       'Las 41 frases hechas que siguen en frecuencia a las del grupo frases hechas 1: vivas y conocidas, pero menos oídas a diario. Mismo formato de tarjeta y de ayuda.',
       'migracion'
WHERE NOT EXISTS (SELECT 1 FROM word_groups WHERE title = 'frases hechas 2 - las 41 siguientes');

