INSERT OR IGNORE INTO word_es_groups (word_es_id, group_id) VALUES ((SELECT word_es_id_b FROM word_es_relations WHERE word_es_id_a = (SELECT id FROM words_es WHERE notes = 'frases hechas: zich te goed doen aan' AND word_type = 'PHRASE' LIMIT 1) AND relation_type = 'EXAMPLE' LIMIT 1), (SELECT id FROM word_groups WHERE title = 'frases hechas 2 - las 41 siguientes'));
DELETE FROM word_es_groups WHERE word_es_id IN ((SELECT id FROM words_es WHERE notes = 'frases hechas: zich te goed doen aan' AND word_type = 'PHRASE' LIMIT 1), (SELECT word_es_id_b FROM word_es_relations WHERE word_es_id_a = (SELECT id FROM words_es WHERE notes = 'frases hechas: zich te goed doen aan' AND word_type = 'PHRASE' LIMIT 1) AND relation_type = 'EXAMPLE' LIMIT 1)) AND group_id = (SELECT id FROM word_groups WHERE title = 'frases hechas 1 - las 50 más usadas');

